+
+    .intro {
+      max-width: 36rem;
+      margin: 1rem 0 2rem;
+      color: var(--muted);
+      font-size: 1.05rem;
+      line-height: 1.6;
+    }
+
+    .contact-form {
+      display: grid;
+      gap: 1.25rem;
