+
+    .form-field {
+      display: grid;
+      gap: 0.5rem;
+    }
+
+    label {
+      font-size: 0.95rem;
+      font-weight: 700;
+    }
+
+    .required-note {
+      color: var(--muted);
+      font-weight: 500;
+    }
+
+    input {
+      width: 100%;
+      min-height: 3.25rem;
+      padding: 0.85rem 1rem;
+      color: var(--text);
+      font: inherit;
+      background: #ffffff;
+      border: 1px solid var(--border);
