+
+    .helper-text {
+      margin: 0;
+      color: var(--muted);
+      font-size: 0.9rem;
+      line-height: 1.45;
+    }
+
+    button {
+      justify-self: start;
+      min-height: 3.25rem;
+      margin-top: 0.5rem;
+      padding: 0.9rem 1.4rem;
+      color: #ffffff;
+      font: inherit;
+      font-weight: 800;
