+
+    button:hover {
+      background: linear-gradient(135deg, var(--primary-dark), #4338ca);
+      box-shadow: 0 16px 32px rgba(37, 99, 235, 0.3);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible {
+      outline: 0.25rem solid var(--ring);
+      outline-offset: 0.2rem;
+    }
+
