<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Support Contact Form</title>
  <style>
    :root {
      color-scheme: light;
      --background: #f5f7fb;
      --surface: #ffffff;
      --text: #172033;
      --muted: #667085;
      --border: #d8deea;
      --primary: #2563eb;
      --primary-dark: #1d4ed8;
      --ring: rgba(37, 99, 235, 0.24);
      --shadow: 0 24px 60px rgba(23, 32, 51, 0.12);
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 32rem),
        linear-gradient(135deg, #f8fbff 0%, var(--background) 100%);
    }

    main {
      display: grid;
      min-height: 100vh;
      place-items: center;
      padding: 2rem;
    }

    .support-card {
      width: min(100%, 44rem);
      padding: clamp(1.5rem, 4vw, 3rem);
      background: rgba(255, 255, 255, 0.92);
      border: 1px solid rgba(216, 222, 234, 0.82);
      border-radius: 1.5rem;
      box-shadow: var(--shadow);
      backdrop-filter: blur(16px);
    }

    .eyebrow {
      margin: 0 0 0.75rem;
      color: var(--primary);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.2rem);
      line-height: 1.05;
      letter-spacing: -0.05em;
    }

    .intro {
      max-width: 36rem;
      margin: 1rem 0 2rem;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.6;
    }

    .contact-form {
      display: grid;
      gap: 1.25rem;
    }

    .form-field {
      display: grid;
      gap: 0.5rem;
    }

    label {
      font-size: 0.95rem;
      font-weight: 700;
    }

    .required-note {
      color: var(--muted);
      font-weight: 500;
    }

    input {
      width: 100%;
      min-height: 3.25rem;
      padding: 0.85rem 1rem;
      color: var(--text);
      font: inherit;
      background: #ffffff;
      border: 1px solid var(--border);
      border-radius: 0.9rem;
      outline: none;
      transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
    }

    input:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 0.25rem var(--ring);
    }

    input:hover {
      border-color: #b8c2d6;
    }

    .helper-text {
      margin: 0;
      color: var(--muted);
      font-size: 0.9rem;
      line-height: 1.45;
    }

    button {
      justify-self: start;
      min-height: 3.25rem;
      margin-top: 0.5rem;
      padding: 0.9rem 1.4rem;
      color: #ffffff;
      font: inherit;
      font-weight: 800;
      background: linear-gradient(135deg, var(--primary), #4f46e5);
      border: 0;
      border-radius: 999px;
      box-shadow: 0 14px 28px rgba(37, 99, 235, 0.24);
      cursor: pointer;
      transition: box-shadow 160ms ease, transform 160ms ease, background 160ms ease;
    }

    button:hover {
      background: linear-gradient(135deg, var(--primary-dark), #4338ca);
      box-shadow: 0 16px 32px rgba(37, 99, 235, 0.3);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 0.25rem solid var(--ring);
      outline-offset: 0.2rem;
    }

    @media (max-width: 36rem) {
      main {
        padding: 1rem;
      }

      .support-card {
        border-radius: 1rem;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script>
    const Field = ({ id, label, type, name, autocomplete, required = false, helperText = "", placeholder = "" }) => `
      <div class="form-field">
        <label for="${id}">
          ${label}${required ? ' <span class="required-note">(required)</span>' : ""}
        </label>
        <input
          id="${id}"
          name="${name}"
          type="${type}"
          autocomplete="${autocomplete}"
          placeholder="${placeholder}"
          ${required ? "required" : ""}
          ${helperText ? `aria-describedby="${id}-helper"` : ""}
        >
        ${helperText ? `<p class="helper-text" id="${id}-helper">${helperText}</p>` : ""}
      </div>
    `;

    const ContactForm = () => `
      <form class="contact-form" action="#" method="post">
        ${Field({
          id: "full-name",
          label: "Full name",
          type: "text",
          name: "fullName",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Morgan"
        })}
        ${Field({
          id: "email",
          label: "Email address",
          type: "email",
          name: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@example.com"
        })}
        ${Field({
          id: "phone",
          label: "Phone number",
          type: "tel",
          name: "phone",
          autocomplete: "tel",
          helperText: "Use digits with an optional country code, for example +1 555 123 4567.",
          placeholder: "+1 555 123 4567"
        })}
        <button type="submit">Contact support</button>
      </form>
    `;

    const SupportPage = () => `
      <section class="support-card" aria-labelledby="support-heading">
        <p class="eyebrow">Support</p>
        <h1 id="support-heading">How can we help?</h1>
        <p class="intro">
          Send our team your contact details and we will route your request to the right support specialist.
        </p>
        ${ContactForm()}
      </section>
    `;

    document.getElementById("root").innerHTML = SupportPage();
  </script>
</body>
</html>
